  angefragt: "Netzanfrage gestellt",
  zusage: "Netzanschlusszusage liegt vor",
  reserviert: "Kapazität reserviert",
  vorhanden: "Anschluss vorhanden (Bestand)",
};

export const FLAECHE_NUTZUNG = {
  acker: "Ackerland",
  gruenland: "Grünland",
  konversion: "Konversionsfläche",
  gewerbe: "Gewerbe- / Parkfläche",
  sonstige: "Sonstige",
};

export const PREIS_MODUS = {
  gesamt: "Kaufpreis gesamt",
  proKwp: "Preis je kWp",
  anfrage: "Auf Anfrage",
};

export const DOKUMENT_KATEGORIEN = {
  allgemein: "Allgemein",
  datenraum: "Datenraum (nur nach NDA)",
  vertrag: "Vertrag / Angebot",
  plan: "Lageplan / Karte",
};

/** Beziehungsarten für Nachrichten und Dokumente */
export const BEZUG_ARTEN = ["vorgang", "flaeche", "projekt", "interesse", "nutzer"];
export const BEZUG_LABEL = { vorgang: "Anfrage", flaeche: "Fläche", projekt: "Projekt", interesse: "Projektinteresse", nutzer: "Allgemein" };

/** Upload-Regeln (Demo und Frappe identisch) */
export const UPLOAD = {
  maxBytes: 10 * 1024 * 1024,
  typen: { "application/pdf": "pdf", "image/jpeg": "jpg", "image/png": "png" },
};

/** Text der Klick-NDA – Version wird mit Zeitstempel und IP protokolliert. */
export const NDA = {
  version: "2026-09",
  titel: "Vertraulichkeitsvereinbarung (Klick-NDA)",
  absaetze: [
    "Ich verpflichte mich, alle Informationen und Unterlagen zu diesem Projekt, die mir über die Projektbörse von ÖkoInvest zugänglich gemacht werden, vertraulich zu behandeln und ausschließlich zur Prüfung eines möglichen Erwerbs bzw. einer Beteiligung zu verwenden.",
    "Eine Weitergabe an Dritte ist nur an Berater (Rechtsanwälte, Steuerberater, finanzierende Banken) zulässig, die ihrerseits zur Verschwiegenheit verpflichtet sind.",
    "Ich werde den Projektanbieter, Flächeneigentümer, Netzbetreiber oder die Standortgemeinde nicht ohne vorherige Abstimmung mit ÖkoInvest direkt kontaktieren (Umgehungsschutz).",
    "Die Verpflichtung gilt für zwei Jahre ab Annahme. Auf Verlangen lösche ich erhaltene Unterlagen.",
  ],
  // ENTWURF – Wortlaut vor Livegang juristisch prüfen lassen (siehe docs/PLATTFORM.md).
};

/** Provisionsvereinbarung für Anbieter – Text wird mit Zeitstempel und IP protokolliert. */
export const PROVISIONS_VEREINBARUNG = {
  version: "2026-09",
};

/**
 * Benachrichtigungen (Glocke im Portal-Kopf) – Ereignisarten.
 * `mail`: Standard für den E-Mail-Versand (je Konto änderbar), `admin`: nur für das Backoffice relevant.
 */
export const BENACHRICHTIGUNG_ARTEN = {
  status: { label: "Statuswechsel", text: "Ihr Vorgang, Ihre Fläche oder Ihr Projekt hat einen neuen Status.", mail: true },
  nachricht: { label: "Neue Nachrichten", text: "Das Backoffice hat Ihnen geschrieben oder ein Dokument bereitgestellt.", mail: true },
  nda: { label: "NDA-Freigabe & Datenraum", text: "Ihr Datenraum wurde freigegeben oder Ihre LOI beantwortet.", mail: true, rollen: ["investor"] },
  suchprofil: { label: "Neue passende Projekte", text: "Ein neu veröffentlichtes Projekt passt zu Ihrem Suchprofil.", mail: true, rollen: ["investor"] },
  anfrage: { label: "Neue Anfragen", text: "Über die Website ist eine neue Anfrage eingegangen.", mail: true, admin: true },
  aufgabe: { label: "Aufgaben & Wiedervorlagen", text: "Ihnen wurde eine Aufgabe zugewiesen oder eine Wiedervorlage ist fällig.", mail: true, admin: true },
  // Login, Sicherheit & Teams: E-Mail immer (nicht abschaltbar, daher nicht in den Einstellungen)
  sicherheit: { label: "Sicherheit & Anmeldungen", text: "Anmeldung von einem neuen Gerät, Zwei-Faktor, E-Mail-Änderung, Kontosperre.", mail: true, fest: true },
};
export const BENACHRICHTIGUNG_ART_IDS = Object.keys(BENACHRICHTIGUNG_ARTEN);

/** Standard-Einstellungen „per E-Mail benachrichtigen“ je Ereignisart */
export function mailEinstellungenStandard() {
  return Object.fromEntries(Object.entries(BENACHRICHTIGUNG_ARTEN).map(([k, a]) => [k, !!a.mail]));
}

/** Ereignisarten, die für ein Konto mit diesen Rollen sichtbar/einstellbar sind */
export function benachrichtigungArtenFuer(rollen = []) {
  const admin = rollen.includes("admin");
  return BENACHRICHTIGUNG_ART_IDS.filter((k) => {
    const a = BENACHRICHTIGUNG_ARTEN[k];
    if (a.fest) return false; // immer per E-Mail, nicht einstellbar
    if (a.admin) return admin;
    if (a.rollen) return admin || a.rollen.some((r) => rollen.includes(r));
    return true;
  });
}

/** Aufgaben / Wiedervorlagen im Backoffice */
export const AUFGABE_STATUS = { offen: "Offen", erledigt: "Erledigt" };
export const AUFGABE_BEZUG_ARTEN = ["vorgang", "flaeche", "projekt", "interesse"];

/** Suchprofil-Alarm: Standard-Schwelle des Matching-Scores (Investor kann 50–100 wählen) */
export const SUCHPROFIL_SCHWELLE = { standard: 70, min: 50, max: 100 };
// src/lib/plattform/rechte.js
//
// Feine Rechte im Backoffice: Unterrollen für Konten mit der Rolle `admin`.
//
//   leitung      – alles (Standard für Backoffice-Konten ohne Unterrolle – rückwärtskompatibel)
//   akquise      – Anfragen, Flächen-Pipeline, CRM, Aufgaben, Vorlagen
//   transaktion  – Projekte, NDA/LOI, CRM, Aufgaben, Vorlagen
//   buchhaltung  – Provisionen, Berichte, Exporte
//   lesen        – nur lesen (keine Änderungen)
//
// Stufen je Bereich: 0 = kein Zugriff, 1 = lesen, 2 = schreiben. Mehrere Unterrollen → Maximum je Bereich.
// Durchgesetzt in allen Admin-APIs (server/route.js → adminRechtPruefen) und Admin-Seiten (server/seite.js);
// die Seitenleiste blendet Bereiche ohne Leserecht aus. Frappe: plattform/rechte.py (gleiche Tabelle).
//
// Client- und serverseitig nutzbar (keine Node-Importe).

export const BACKOFFICE_ROLLEN = {
  leitung: { label: "Leitung", text: "Vollzugriff inkl. Rechteverwaltung, Automationen und Nutzer." },
  akquise: { label: "Akquise", text: "Anfragen, Flächen-Pipeline, Gebiete, CRM, Aufgaben und Vorlagen." },
  transaktion: { label: "Transaktion", text: "Projektfreigabe, NDA & LOI, Verkauf, CRM und Aufgaben." },
  buchhaltung: { label: "Buchhaltung", text: "Provisionen und Rechnungsstatus, Berichte und Exporte." },
  lesen: { label: "Nur lesen", text: "Sieht alle Bereiche außer der Rechteverwaltung, ändert nichts." },
};
export const BACKOFFICE_ROLLEN_IDS = Object.keys(BACKOFFICE_ROLLEN);

export const BEREICHE = {
  cockpit: "Cockpit",
  vorgaenge: "Vorgänge",
  flaechen: "Flächen",
  akquise: "Akquise & Gebiete",
  projekte: "Projekte",
  interessen: "NDA & LOI",
  provisionen: "Provisionen",
  aufgaben: "Aufgaben",
  crm: "CRM",
  vorlagen: "Vorlagen",
  automationen: "Automationen",
  berichte: "Berichte",
  export: "CSV-Export",
  postausgang: "Postausgang",
  nutzer: "Nutzer",
  protokoll: "Protokoll",
  rechte: "Rechte",
  sonstiges: "Weitere Admin-Funktionen",
};
export const BEREICH_IDS = Object.keys(BEREICHE);

// Reihenfolge der Spalten: leitung, akquise, transaktion, buchhaltung, lesen
const M = {
  cockpit: [2, 1, 1, 1, 1],
  vorgaenge: [2, 2, 1, 1, 1],
  flaechen: [2, 2, 1, 0, 1],
  akquise: [2, 2, 1, 0, 1],
  projekte: [2, 1, 2, 1, 1],
  interessen: [2, 0, 2, 1, 1],
  provisionen: [2, 0, 1, 2, 1],
  aufgaben: [2, 2, 2, 2, 1],
  crm: [2, 2, 2, 1, 1],
  vorlagen: [2, 2, 2, 1, 1],
  automationen: [2, 1, 1, 0, 1],
  berichte: [2, 1, 1, 2, 1],
  export: [2, 1, 1, 1, 0],
  postausgang: [2, 1, 1, 0, 1],
  nutzer: [2, 1, 1, 1, 1],
  protokoll: [2, 1, 1, 1, 1],
  rechte: [2, 0, 0, 0, 0],
  sonstiges: [2, 1, 1, 1, 1],
};
const SPALTE = { leitung: 0, akquise: 1, transaktion: 2, buchhaltung: 3, lesen: 4 };

/** Rechte-Matrix { bereich: { rolle: stufe } } – für Anzeige und Prüfung */
export const RECHTE_MATRIX = Object.fromEntries(
  Object.entries(M).map(([b, stufen]) => [b, Object.fromEntries(BACKOFFICE_ROLLEN_IDS.map((r) => [r, stufen[SPALTE[r]]]))])
);

/** Unterrollen eines Kontos (ohne Angabe → leitung). Nicht-Admins → [] */
export function unterrollen(n) {
  if (!n?.rollen?.includes("admin")) return [];
  const r = (Array.isArray(n.backofficeRollen) ? n.backofficeRollen : String(n.backofficeRollen || "").split(","))
    .map((x) => String(x).trim())
    .filter((x) => BACKOFFICE_ROLLEN[x]);
  return r.length ? [...new Set(r)] : ["leitung"];
}

/** Stufe (0–2) eines Kontos in einem Bereich */
export function stufe(n, bereich) {
  const zeile = RECHTE_MATRIX[bereich] || RECHTE_MATRIX.sonstiges;
  return unterrollen(n).reduce((m, r) => Math.max(m, zeile[r] ?? 0), 0);
}

export const darfLesen = (n, bereich) => stufe(n, bereich) >= 1;
export const darfSchreiben = (n, bereich) => stufe(n, bereich) >= 2;

/** Bereich je Objektart (Statuswechsel, Zuweisung, Aufgaben am Objekt, Export) */
export const BEREICH_FUER_ART = {
  vorgang: "vorgaenge",
  flaeche: "flaechen",
  projekt: "projekte",
  interesse: "interessen",
  provision: "provisionen",
  vorgaenge: "vorgaenge",
  flaechen: "flaechen",
  projekte: "projekte",
  interessen: "interessen",
  provisionen: "provisionen",
};

/** Bereich einer Admin-API aus dem Pfad (/api/admin/<teil>/…) */
const API_BEREICH = {
  uebersicht: "cockpit",
  vorgaenge: "vorgaenge",
  flaechen: "flaechen",
  projekte: "projekte",
  interessen: "interessen",
  provisionen: "provisionen",
  aufgaben: "aufgaben",
  nutzer: "nutzer",
  "demo-links": "nutzer",
  aktivitaeten: "protokoll",
  protokoll: "protokoll",
  postausgang: "postausgang",
  crm: "crm",
  akquise: "akquise",
  gebiete: "akquise",
  automationen: "automationen",
  vorlagen: "vorlagen",
  berichte: "berichte",
  rechte: "rechte",
  dealroom: "interessen", // Deal-Room (Q&A, Datenraum) – Transaktion
  bieter: "interessen", // Bieterverfahren – Transaktion
};

/**
 * Welche Rechte braucht eine Admin-API? Liefert [{ bereich, stufe }] (alle müssen erfüllt sein).
 * `body` wird für Status/Zuweisung (Objektart) und Aufgaben mit Bezug ausgewertet.
 */
export function apiAnforderungen({ pfad, methode = "GET", body, params = {}, recht } = {}) {
  const schreiben = !["GET", "HEAD", "OPTIONS"].includes(String(methode).toUpperCase());
  const teile = String(pfad || "").split("?")[0].split("/").filter(Boolean); // ["api","admin",teil,…]
  const teil = teile[2] || "";
  const st = schreiben ? 2 : 1;
  if (recht) return [].concat(recht).map((r) => (typeof r === "string" ? { bereich: r, stufe: st } : r));
  if (teil === "status" || teil === "zuweisen") {
    return [{ bereich: BEREICH_FUER_ART[body?.art] || "sonstiges", stufe: 2 }];
  }
  if (teil === "export") {
    const art = params?.art || teile[3];
    return [{ bereich: "export", stufe: 1 }, { bereich: BEREICH_FUER_ART[art] || "sonstiges", stufe: 1 }];
  }
  if (teil === "berichte") return [{ bereich: "berichte", stufe: 1 }]; // PDF/CSV-Abruf ist Lesen
  const anf = [{ bereich: API_BEREICH[teil] || "sonstiges", stufe: st }];
  if (teil === "aufgaben" && schreiben && body?.bezugArt && BEREICH_FUER_ART[body.bezugArt]) {
    anf.push({ bereich: BEREICH_FUER_ART[body.bezugArt], stufe: 1 });
  }
  if (teil === "automationen" && teile[3] === "testlauf") anf[0].stufe = 1; // Testlauf ändert nichts
  if (teil === "vorlagen" && teile[3] === "vorschau") anf[0].stufe = 1;
  return anf;
}

/** Fehlende Rechte (leer = erlaubt) */
export function fehlendeRechte(n, anforderungen) {
  return anforderungen.filter((a) => stufe(n, a.bereich) < a.stufe);
}

/** Bereich einer Admin-Seite (/portal/admin/<teil>) */
const SEITEN_BEREICH = {
  "": "cockpit",
  aufgaben: "aufgaben",
  vorgaenge: "vorgaenge",
  flaechen: "flaechen",
  akquise: "akquise",
  projekte: "projekte",
  interessen: "interessen",
  deals: "provisionen",
  nutzer: "nutzer",
  postausgang: "postausgang",
  crm: "crm",
  automationen: "automationen",
  vorlagen: "vorlagen",
  berichte: "berichte",
  protokoll: "protokoll",
  rechte: "rechte",
};

export function seitenBereich(pfad) {
  const teile = String(pfad || "").split("?")[0].split("/").filter(Boolean); // ["portal","admin",teil]
  if (teile[0] !== "portal" || teile[1] !== "admin") return null;
  return SEITEN_BEREICH[teile[2] || ""] || "sonstiges";
}

export const STUFE_LABEL = ["–", "lesen", "schreiben"];
// src/lib/plattform/organisation.js
//
// Firmenkonten (Organisationen & Teams) und Konto-Komfort – Stammlisten und Rechtematrix.
// Client- und serverseitig nutzbar (keine Node-Importe). Frappe: plattform/konstanten.py (identisch).
//
// Rechte je Teamrolle (gelten für Objekte der Organisation: Flächen, Projekte, Interessen, Suchprofil):
//   lesen     – sehen (Listen im Organisationskontext, Detailseiten, Nachrichten, Dokumente, Datenraum nach NDA)
//   mitglied  – zusätzlich bearbeiten, Statusschritte als Eigentümer, hochladen, Nachrichten senden, anlegen
//   admin     – zusätzlich Mitglieder einladen/entfernen, Rollen bis „Admin“ vergeben, Stammdaten ändern
//   inhaber   – zusätzlich Inhaberschaft übertragen, Organisation löschen (genau ein Inhaber)

export const ORGANISATION_ARTEN = {
  investmenthaus: { label: "Investmenthaus / Investor", text: "Projekte prüfen, NDA und Datenraum im Team, gemeinsames Suchprofil." },
  projektentwickler: { label: "Projektentwickler", text: "Projekte gemeinsam in die Börse stellen und Interessenten betreuen." },
  stadtwerk: { label: "Stadtwerk / Kommune", text: "Flächen, Projekte und Beteiligungsmodelle im Team verfolgen." },
  betrieb: { label: "Betrieb / Unternehmen", text: "Flächen, Anfragen und Unterlagen des Betriebs an einem Ort." },
};
export const ORGANISATION_ART_IDS = Object.keys(ORGANISATION_ARTEN);

export const TEAM_ROLLEN = {
  inhaber: { label: "Inhaber", stufe: 4, text: "Volle Rechte, überträgt die Inhaberschaft, löscht die Organisation." },
  admin: { label: "Admin", stufe: 3, text: "Verwaltet Mitglieder und Einladungen, bearbeitet alles." },
  mitglied: { label: "Mitglied", stufe: 2, text: "Sieht und bearbeitet die Objekte der Organisation." },
  lesen: { label: "Nur lesen", stufe: 1, text: "Sieht die Objekte der Organisation, ändert nichts." },
};
export const TEAM_ROLLEN_IDS = Object.keys(TEAM_ROLLEN);
/** Rollen, die per Einladung vergeben werden können (Inhaber nur per Übertragung) */
export const EINLADUNG_ROLLEN = ["admin", "mitglied", "lesen"];

export const teamStufe = (rolle) => TEAM_ROLLEN[rolle]?.stufe || 0;
export const darfTeamLesen = (rolle) => teamStufe(rolle) >= 1;
export const darfTeamSchreiben = (rolle) => teamStufe(rolle) >= 2;
export const darfTeamVerwalten = (rolle) => teamStufe(rolle) >= 3;
export const teamRolleLabel = (r) => TEAM_ROLLEN[r]?.label || r;

/** Objektarten, die einer Organisation gehören können */
export const ORGANISATION_OBJEKTE = ["flaeche", "projekt", "interesse"];

/** Einladung: Gültigkeit in Tagen */
export const EINLADUNG_TAGE = 7;
export const MAX_MITGLIEDER = 200;

// ---------------------------------------------------------------- Konto-Komfort

/** Avatarfarben – ausschließlich Tokens des Design-Systems */
export const AVATAR_FARBEN = {
  navy: { label: "Navy", klasse: "bg-navy-700 text-white" },
  gruen: { label: "Grün", klasse: "bg-ov-600 text-white" },
  dunkelgruen: { label: "Dunkelgrün", klasse: "bg-ov-800 text-white" },
  sonne: { label: "Sonne", klasse: "bg-sun-400 text-navy-950" },
  sand: { label: "Sand", klasse: "bg-sand-100 text-ink-900 ring-1 ring-inset ring-ink-200" },
  grau: { label: "Grau", klasse: "bg-ink-700 text-white" },
};
export const avatarKlasse = (farbe) => (AVATAR_FARBEN[farbe] || AVATAR_FARBEN.navy).klasse;

export const SPRACHEN = { de: "Deutsch", en: "English (in Vorbereitung)" };

export function komfortStandard() {
  return { farbe: "navy", sprache: "de", kanaele: { email: true, sicherheitEmail: true } };
}

/** Komfort-Einstellungen bereinigen (Positivliste) */
export function komfortBereinigen(k = {}, basis = komfortStandard()) {
  const kanaele = k?.kanaele && typeof k.kanaele === "object" ? k.kanaele : {};
  return {
    farbe: Object.hasOwn(AVATAR_FARBEN, k?.farbe) ? k.farbe : basis.farbe,
    sprache: Object.hasOwn(SPRACHEN, k?.sprache) ? k.sprache : basis.sprache,
    kanaele: {
      email: typeof kanaele.email === "boolean" ? kanaele.email : basis.kanaele?.email ?? true,
