// src/lib/plattform/fehler.js
//
// Einheitlicher Fehler für Backend und API. `status` wird 1:1 als HTTP-Status
// zurückgegeben, `message` ist für Nutzer bestimmt (deutsch, ohne Interna).

const CODES = {
  400: "ungueltig",
  401: "nicht_angemeldet",
  403: "verboten",
  404: "nicht_gefunden",
  409: "konflikt",
  413: "zu_gross",
  415: "typ",
  422: "validierung",
  429: "zu_viele",
  502: "backend",
  503: "nicht_konfiguriert",
};

export class PlattformFehler extends Error {
  constructor(status, message, code) {
    super(message);
    this.name = "PlattformFehler";
    this.status = status;
    this.code = code || CODES[status] || "fehler";
  }
}

export const nichtAngemeldet = () => new PlattformFehler(401, "Bitte melden Sie sich an.");
export const verboten = (text = "Dafür fehlt Ihnen die Berechtigung.") => new PlattformFehler(403, text);
export const nichtGefunden = (text = "Nicht gefunden.") => new PlattformFehler(404, text);
export const ungueltig = (text) => new PlattformFehler(422, text);
export const konflikt = (text) => new PlattformFehler(409, text);
// src/lib/plattform/backend/demo/hilfen.js – kleine Helfer des Demo-Backends

import { createHash, randomBytes } from "node:crypto";

const ALPHABET = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ"; // ohne 0/O/1/I

/** Kennung wie V-26-7KQ2XM (Präfix, Jahr, 6 zufällige Zeichen ≈ 30 Bit) */
export function neueId(praefix, laenge = 6) {
  const b = randomBytes(laenge);
  let s = "";
  for (let i = 0; i < laenge; i++) s += ALPHABET[b[i] % ALPHABET.length];
  return `${praefix}-${String(new Date().getFullYear()).slice(2)}-${s}`;
}

export const jetzt = () => new Date().toISOString();

/** ISO-Zeitpunkt relativ zu jetzt (Tage, negativ = Vergangenheit) */
export const vorTagen = (tage, stunden = 0) => new Date(Date.now() - (tage * 24 + stunden) * 3600 * 1000).toISOString();

export const sha256 = (s) => createHash("sha256").update(s).digest("hex");

/** Zufälliges Einmal-Token (256 Bit, base64url) */
export const zufallsToken = () => randomBytes(32).toString("base64url");

export function slugify(s) {
  return String(s || "")
    .toLowerCase()
    .replace(/ä/g, "ae")
    .replace(/ö/g, "oe")
    .replace(/ü/g, "ue")
    .replace(/ß/g, "ss")
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 80);
}

