      benachrichtigungen.push(B(n.investor.id, "suchprofil", `Passendes Projekt: ${p.titel}`, `${m.score} % Passung${m.gruende.length ? ` · ${m.gruende.join(", ")}` : ""}`, `/portal/boerse/${p.id}`, Math.max(0, Math.round((Date.now() - new Date(p.veroeffentlichtAm).getTime()) / 86400e3)), p !== projekte[2], "projekt", p.id));
    }
  }
  const E = (u, art, betreff, textInhalt, link, tage, linkText = "Zum Portal") => ({
    id: neueId("E"), am: vorTagen(tage, 1), an: u.email, anName: `${u.vorname} ${u.nachname}`, nutzerId: u.id, art, betreff, text: textInhalt, link, linkText,
    hinweis: "Aus Gründen der Vertraulichkeit enthält diese E-Mail keine Inhalte. Bitte melden Sie sich im Portal an.",
  });
  const postausgang = [
    E(n.flaeche, "status", "Neuigkeiten zu Ihrem Vorgang – ÖkoInvest", "Der Status eines Ihrer Vorgänge hat sich geändert. Details finden Sie im Portal.", `/portal/flaechen/${f1.id}`, 3),
    E(n.unternehmen, "status", "Neuigkeiten zu Ihrem Vorgang – ÖkoInvest", "Der Status eines Ihrer Vorgänge hat sich geändert. Details finden Sie im Portal.", `/portal/anfragen/${vorgaenge[5].id}`, 4),
    E(n.investor, "suchprofil", "Neues Projekt passend zu Ihrem Suchprofil – ÖkoInvest", `In der Projektbörse wurde ein Projekt veröffentlicht, das zu Ihrem Suchprofil passt: „${p1.titel}“. Vertrauliche Angaben und Datenraum sehen Sie nach Klick-NDA im Portal.`, `/portal/boerse/${p1.id}`, 40),
    E(n.admin, "anfrage", "Neue Anfrage über die Website – ÖkoInvest", "Über die Website ist eine neue Anfrage eingegangen.", `/portal/admin/vorgaenge/${vorgaenge[8].id}`, 2),
  ].sort((a, b) => b.am.localeCompare(a.am));

  return {
    erstelltAm: new Date().toISOString(),
    hinweis: "Demo-Datenbank der ÖkoInvest-Plattform – alle Daten fiktiv.",
    nutzer,
    vorgaenge,
    flaechen,
    projekte,
    interessen,
    provisionen,
    nachrichten,
    dokumente,
    aktivitaeten,
    tokens: [],
    demoLinks: [],
    benachrichtigungen,
    postausgang,
    aufgaben,
  };
}
// src/lib/plattform/server/passwort.js
//
// Passwort-Hashing für das Demo-Backend: scrypt mit 16 Byte Salt, Vergleich
// zeitkonstant. Format: scrypt$N$r$p$<salt b64>$<hash b64> (Parameter im Hash,
// damit sie später erhöht werden können). Frappe nutzt sein eigenes Verfahren.

import { randomBytes, scrypt, timingSafeEqual } from "node:crypto";

const N = 16384;
const R = 8;
const P = 1;
const LAENGE = 64;

function scryptAsync(passwort, salt, n, r, p) {
  return new Promise((resolve, reject) =>
    scrypt(passwort.normalize("NFKC"), salt, LAENGE, { N: n, r, p, maxmem: 64 * 1024 * 1024 }, (err, key) => (err ? reject(err) : resolve(key)))
  );
}

export async function passwortHash(passwort) {
  const salt = randomBytes(16);
  const key = await scryptAsync(String(passwort), salt, N, R, P);
  return `scrypt$${N}$${R}$${P}$${salt.toString("base64")}$${key.toString("base64")}`;
}

// Für unbekannte E-Mail-Adressen trotzdem rechnen – gleiche Antwortzeit (keine Konto-Enumeration)
let attrappe = null;

export async function passwortPruefen(passwort, gespeichert) {
  if (!gespeichert) {
    attrappe ||= await passwortHash("attrappe-ohne-konto");
    gespeichert = attrappe;
    passwort = `${passwort}-x`;
  }
  const teile = String(gespeichert).split("$");
  if (teile.length !== 6 || teile[0] !== "scrypt") return false;
  const [, n, r, p, salt, hash] = teile;
  const soll = Buffer.from(hash, "base64");
  const ist = await scryptAsync(String(passwort ?? ""), Buffer.from(salt, "base64"), Number(n), Number(r), Number(p));
  return soll.length === ist.length && timingSafeEqual(soll, ist);
}
// src/lib/plattform/backend/demo/backoffice.js
//
// Backoffice-Ausbau des Demo-Backends (CRM, Akquise, Automationen, Vorlagen, Berichte, Rechte,
// Hash-Kette). demo.js re-exportiert alle Operationen von hier und ruft
//   werkzeugeSetzen({...})        – interne Helfer (Nachricht, Postausgang, Statuswechsel …)
//   backofficeEreignis(db, e)     – bei neuem Vorgang, Statuswechsel, Dokument, Suchprofil-Treffer
//   protokollAnhaengen(db, e)     – Aktivitätsprotokoll mit Hash-Kette
// auf. Operationen: siehe BACKOFFICE_OPERATIONEN in backend/frappe/backoffice.js.

import { boSeedSetzen, boSicher } from "./bo-kern";
import { boSeed } from "./bo-seed";
import { crmAusVorgang } from "./crm";
import { automationAusfuehren } from "./automation";

boSeedSetzen(boSeed);

export { werkzeugeSetzen } from "./bo-kern";
export { protokollAnhaengen } from "./kette";

/**
 * Ereignis aus dem Kern (synchron, innerhalb der laufenden Schreibtransaktion).
 * e = { typ: vorgang_neu|status|dokument|suchprofil, art, objekt, von?, nach?, extra? }
 * Fehler im Backoffice-Teil dürfen den eigentlichen Vorgang nie verhindern → nur Log.
 */
export function backofficeEreignis(db, e) {
  try {
    boSicher(db);
    if (e.typ === "vorgang_neu") crmAusVorgang(db, e.objekt);
    automationAusfuehren(db, e);
  } catch (fehler) {
    console.error("[plattform-backoffice] Ereignis", e?.typ, e?.objekt?.id, fehler);
  }
}

