    quotenJahr: r.jahr ? quoten(r.jahr) : null,
    co2JahrKg: (r.jahr?.erzeugungKwh || 0) * CO2_KG_PRO_KWH,
    quelle: messdatenQuelle(),
    messfehler,
  };
}

