  const z = zeitraumPruefen({ von: suche.get("von"), bis: suche.get("bis"), aufloesung: suche.get("aufloesung") });
  const r = await messdaten().reihe(a, z);
  const punkte = mitSoll(a, r.punkte || [], r.aufloesung || z.aufloesung);
