// src/components/Boerse/KarteGeo.js
//
// Stilisierte Geometrie der DACH-Karte (bewusst grob, Umrisse vereinfacht): Länderumrisse als
// Längen-/Breitengrad-Polygone und je Bundesland/Kanton EIN Mittelpunkt. Projekte werden nur
// je Bundesland/Kanton gebündelt – nie mit genauer Lage (öffentliche Börse zeigt nur die Region).

/** Abstandstreue Zylinderprojektion für ~50° N, ViewBox 470 × 600 */
export const KARTE = { breite: 470, hoehe: 600 };
const LON0 = 5.6;
const LAT0 = 55.25;
const SX = 39.4; // 62 × cos(50,5°)
const SY = 62;
export const projiziere = ([lon, lat]) => [Math.round((lon - LON0) * SX * 10) / 10, Math.round((LAT0 - lat) * SY * 10) / 10];

const pfad = (punkte) => `M${punkte.map((p) => projiziere(p).join(",")).join("L")}Z`;

const DE = [
  [8.66, 54.91], [9.45, 54.83], [9.95, 54.78], [10.03, 54.55], [10.85, 54.36], [11.1, 54.52], [10.87, 54.08], [11.45, 54.02], [12.1, 54.18],
  [12.5, 54.47], [13.1, 54.38], [13.38, 54.65], [13.7, 54.35], [13.85, 54.1], [14.23, 53.93], [14.28, 53.7], [14.41, 53.33], [14.13, 52.83],
  [14.64, 52.57], [14.53, 52.25], [14.72, 51.93], [14.6, 51.55], [15.03, 51.28], [14.82, 50.87], [14.28, 50.97], [14.0, 50.82], [13.55, 50.7],
export const REGION_MITTE = {
  DE: {
    "Schleswig-Holstein": [9.7, 54.2], Hamburg: [10.0, 53.55], Bremen: [8.8, 53.08], Niedersachsen: [9.2, 52.7], "Mecklenburg-Vorpommern": [12.4, 53.8],
    Berlin: [13.4, 52.52], Brandenburg: [13.75, 52.05], "Sachsen-Anhalt": [11.7, 52.0], "Nordrhein-Westfalen": [7.5, 51.45], Hessen: [9.0, 50.6],
    Thüringen: [11.0, 50.9], Sachsen: [13.3, 51.0], "Rheinland-Pfalz": [7.4, 49.9], Saarland: [6.95, 49.4], "Baden-Württemberg": [9.0, 48.6],
    Bayern: [11.5, 48.9],
  },
  AT: {
    Vorarlberg: [9.9, 47.25], Tirol: [11.4, 47.2], Salzburg: [13.1, 47.4], Kärnten: [13.9, 46.75], Steiermark: [15.1, 47.3], Oberösterreich: [14.0, 48.1],
    Niederösterreich: [15.7, 48.3], Wien: [16.37, 48.2], Burgenland: [16.5, 47.5],
  },
  CH: {
    Aargau: [8.15, 47.4], "Appenzell Ausserrhoden": [9.35, 47.37], "Appenzell Innerrhoden": [9.42, 47.3], "Basel-Landschaft": [7.7, 47.45], "Basel-Stadt": [7.6, 47.56],
    Bern: [7.6, 46.8], Freiburg: [7.1, 46.7], Genf: [6.15, 46.2], Glarus: [9.05, 47.0], Graubünden: [9.6, 46.65], Jura: [7.2, 47.35], Luzern: [8.1, 47.05],
    Neuenburg: [6.8, 47.0], Nidwalden: [8.4, 46.93], Obwalden: [8.25, 46.85], Schaffhausen: [8.6, 47.7], Schwyz: [8.75, 47.05], Solothurn: [7.6, 47.3],
    "St. Gallen": [9.2, 47.2], Tessin: [8.8, 46.3], Thurgau: [9.1, 47.55], Uri: [8.6, 46.75], Waadt: [6.6, 46.6], Wallis: [7.6, 46.2], Zug: [8.5, 47.15], Zürich: [8.65, 47.4],
  },
};

/** Mittelpunkt einer Region (Fallback: Landesmitte) */
export function regionPunkt(land, bundesland) {
  const p = REGION_MITTE[land]?.[bundesland] || LAENDER_PFADE.find((l) => l.id === land)?.label;
  return p ? projiziere(p) : null;
}

