}
MQTT_PRAEFIX = "oekoinvest/v1"
MAX_ZUGAENGE_JE_ANLAGE = 20

DE_REGION = {
	"Schleswig-Holstein": "de-nord", "Hamburg": "de-nord", "Niedersachsen": "de-nord", "Bremen": "de-nord", "Mecklenburg-Vorpommern": "de-nord",
