	zg = zugriff(n, a)
	bo = zg == "backoffice"
	offen = frappe.get_all("Plattform Stoerungsfall", filters={"anlage_id": a.name, "status": ["in", STOERUNG_OFFEN]}, fields=["name", "schwere", "status", "titel", "regel"], limit_page_length=0)
