		"lastprofil": a.lastprofil, "lastJahrKwh": flt(a.last_jahr_kwh), "wechselrichterAnzahl": cint(a.wechselrichter_anzahl) or 1, "beschreibung": a.beschreibung or "",
		"simulation": None,
